    title: "Temps de préparation",
    emoji: "🥩",
    cat: "viande",
    chef: "franceinter",
    chefName: "France Inter",
    time: "45min",
    serves: "6 pers.",
    difficulty: "Facile",
    image: "img/DC9oH96IPNi.jpg",
